      // \u041C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u0438 2 \u0438 3 \u2014 \xAB\u043A\u0440\u0443\u0442\u0438\u0437\u043D\u0430\xBB \u043A\u0440\u0438\u0432\u043E\u0439. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439 \u043F\u043E\u043C\u0435\u043D\u044F\u0442\u044C \u0432 \u0441\u0432\u043E\u0451\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435.
