//  brain \u2014 \u043A\u043E\u043F\u0438\u044F \u043C\u043E\u0437\u0433\u0430 \u043B\u0443\u0447\u0448\u0435\u0439 \u043C\u0430\u0448\u0438\u043D\u044B. \u041C\u0435\u043D\u044F\u0439 \u0435\u0433\u043E \u043F\u0440\u044F\u043C\u043E \u043D\u0430 \u043C\u0435\u0441\u0442\u0435, \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044C \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0443\u0436\u043D\u043E.
